<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { useWorkflowAutomationStore } from '@/stores/workflowAutomation'
import { useWorkflowStore } from '@/stores/workflows'
import { workflowQueueStatuses,workflowQueueTerminal,type WorkflowScheduleRule,type WorkflowDirectoryRule,type WorkflowQueueItem } from '@/types/workflowTrigger'
import type { WorkflowRunRequest } from '@/types/workflow'
import WorkflowDirectoryRuleDialog from './WorkflowDirectoryRuleDialog.vue'
import WorkflowScheduleDialog from './WorkflowScheduleDialog.vue'
import WorkflowScheduleList from './WorkflowScheduleList.vue'
import WorkflowRunDialog from './WorkflowRunDialog.vue'
import Modal from '@/components/ui/Modal.vue'
import { normalizeWorkflowPlan } from '@/utils/workflow'
const emit=defineEmits<{open:[id:string]}>()
const automation=useWorkflowAutomationStore(),workflow=useWorkflowStore()
const ruleTab=ref('schedule'),scheduleEditor=ref<{rule?:WorkflowScheduleRule}>(),deleteSchedule=ref(false)
const editor=ref<{rule?:WorkflowDirectoryRule}>(),expanded=ref(''),filter=ref('waiting'),credentialsItem=ref<WorkflowQueueItem>(),deleteId=ref('')
const visible=computed(()=>automation.items.filter(item=>filter.value==='all'||filter.value==='waiting'&&!workflowQueueTerminal(item.state)&&item.state!=='running'||filter.value==='running'&&item.state==='running'||filter.value==='completed'&&item.state==='completed'||filter.value==='unfinished'&&['failed','stopped','interrupted'].includes(item.state)))
const activeCount=computed(()=>[...automation.rules,...automation.schedules].filter(rule=>rule.enabled).length)
onMounted(()=>automation.initialize())
watch([editor,scheduleEditor,credentialsItem,deleteId],()=>automation.hold('directory-dialog',!!editor.value||!!scheduleEditor.value||!!credentialsItem.value||!!deleteId.value),{immediate:true})
onUnmounted(()=>automation.hold('directory-dialog',false))
function edit(rule?:WorkflowDirectoryRule){ruleTab.value='directory';automation.error='';editor.value={rule}}
async function save(rule:WorkflowDirectoryRule){if(await automation.saveRule(rule)){editor.value=undefined;void automation.tick()}}
async function saveSchedule(rule:WorkflowScheduleRule){if(await automation.saveSchedule(rule)){scheduleEditor.value=undefined;void automation.tick()}}
function scheduleCredentials(rule:WorkflowScheduleRule){const plan=workflow.plans.find(p=>p.id===rule.planId);if(plan)input({id:'session-'+rule.id,ruleId:rule.id,ruleName:rule.name,paths:rule.paths,sourceKey:rule.id,revision:'',plan,outputDirectory:rule.outputDirectory,state:'needs_input',reason:'',createdAt:'',trigger:'schedule'});else automation.error='原方案已删除，请编辑规则重新选择方案'}
function ruleExists(id:string){return [...automation.rules,...automation.schedules].some(rule=>rule.id===id)}
function isRulePaused(item:WorkflowQueueItem){return !item.explicit&&[...automation.rules,...automation.schedules].some(rule=>rule.id===item.ruleId&&!rule.enabled)}
function input(item:WorkflowQueueItem){credentialsItem.value=item;automation.error=''}
function credentialRequest(request:WorkflowRunRequest){if(!credentialsItem.value)return;automation.remember(credentialsItem.value.ruleId,{sourcePassword:request.sourcePassword,sourceEncoding:request.sourceEncoding,passwords:request.passwords});credentialsItem.value=undefined;void automation.tick()}
function sample(rule:WorkflowDirectoryRule):WorkflowQueueItem|undefined {const plan=workflow.plans.find(plan=>plan.id===rule.planId);return plan?{id:'session-'+rule.id,ruleId:rule.id,ruleName:rule.name,sourceKey:rule.root,paths:[rule.root],revision:'',plan,outputDirectory:rule.outputDirectory,state:'needs_input',reason:'',createdAt:''}:undefined}
function ruleCredentials(rule:WorkflowDirectoryRule){const item=sample(rule);if(item)input(item);else automation.error='原方案已删除，请先编辑规则选择方案；旧排队项仍可单独补密码'}
</script>
<template>
 <section class="automation" data-testid="workflow-automation-panel">
  <header class="automation-heading"><div><h2>自动化与运行队列</h2><p class="muted">按时间或目录变化自动处理。应用运行或托盘驻留时执行；错过时段由你决定。</p></div><div class="buttons"><button class="button" data-testid="workflow-queue-pause" :disabled="automation.saving" @click="automation.pause(!automation.paused)"><i :class="automation.paused?'pi pi-play':'pi pi-pause'"/>{{ automation.paused?'继续队列':'暂停队列' }}</button><button class="button primary" data-testid="workflow-schedule-new" :disabled="!workflow.plans.length" @click="automation.error='';scheduleEditor={}"><i class="pi pi-clock"/>添加定时规则</button><button class="button" data-testid="workflow-rule-new" :disabled="!workflow.plans.length" @click="edit()"><i class="pi pi-plus"/>添加目录规则</button></div></header>
  <p v-if="!workflow.plans.length" class="notice">先保存一套方案，再添加目录或定时规则；原来的监控草稿仍保留原行为。</p>
  <p v-if="automation.paused" class="notice" role="status">队列已暂停启动新工作流。来源仍会观察，正在运行的工作流继续处理。</p>
  <p v-if="automation.error" class="notice failure" data-testid="workflow-automation-error" role="alert">{{ automation.error }}<button class="link ml-3" @click="automation.error='';automation.tick()">重新观察</button></p>
  <div class="stats"><div><strong>{{ activeCount }} / {{ automation.rules.length+automation.schedules.length }}</strong><span>启用规则</span></div><div><strong>{{ automation.waiting.length }}</strong><span>等待与排队</span></div><div><strong>{{ automation.items.filter(item=>item.state==='running').length }}</strong><span>正在运行</span></div><div><strong>{{ automation.items.filter(item=>item.state==='completed').length }}</strong><span>已完成记录</span></div></div>
  <div class="automation-grid">
   <section class="card min-w-0"><div class="section-title"><div class="buttons rule-tabs"><button class="button" :class="{primary:ruleTab==='schedule'}" data-testid="workflow-schedules-tab" @click="ruleTab='schedule'">定时规则 · {{ automation.schedules.length }}</button><button class="button" :class="{primary:ruleTab==='directory'}" data-testid="workflow-directories-tab" @click="ruleTab='directory'">目录规则 · {{ automation.rules.length }}</button></div></div><WorkflowScheduleList v-if="ruleTab==='schedule'" @edit="rule=>{automation.error='';scheduleEditor={rule}}" @credentials="scheduleCredentials" @remove="id=>{deleteSchedule=true;deleteId=id}" @open="id=>emit('open',id)"/><template v-else><div v-if="!automation.rules.length" class="empty"><i class="pi pi-folder-open"/><p>为常用目录保存一条规则</p><small>可以分别归档文件，也可以按项目文件夹处理。</small></div>
    <div class="rule-list custom-scrollbar"><article v-for="rule in automation.rules" :key="rule.id" class="rule" :data-workflow-rule="rule.name"><button class="rule-toggle" :data-rule-toggle="rule.id" :aria-expanded="expanded===rule.id" @click="expanded=expanded===rule.id?'':rule.id"><i class="pi pi-folder"/><span class="min-w-0 flex-1 text-left"><strong>{{ rule.name }}</strong><small>{{ workflow.plans.find(plan=>plan.id===rule.planId)?.name||'原方案已删除' }}</small></span><span class="badge" :class="{enabled:rule.enabled}">{{ rule.enabled?'已启用':'已暂停' }}</span><i :class="expanded===rule.id?'pi pi-chevron-up':'pi pi-chevron-down'"/></button><div v-if="expanded===rule.id" class="rule-details" :data-rule-details="rule.id"><dl><dt>监控目录</dt><dd>{{ rule.root }}</dd><dt>保存位置</dt><dd>{{ rule.outputDirectory }}</dd><dt>触发范围</dt><dd>{{ rule.mode==='folders'?'每个顶层文件夹':(rule.recursive?'文件及子目录':'当前目录文件') }} · {{ rule.extensions||'全部类型' }} · 稳定 {{ rule.settleSeconds }} 秒</dd></dl><p v-if="rule.note" class="muted failure" data-testid="workflow-rule-note">{{ rule.note }}</p><div class="buttons mt-3"><button class="button" :disabled="automation.saving" :data-rule-enabled="rule.id" @click="automation.enable(rule.id,!rule.enabled)">{{ rule.enabled?'暂停规则':'启用规则' }}</button><button class="button" :data-rule-edit="rule.id" @click="edit(rule)">编辑</button><button class="button" :data-rule-credentials="rule.id" @click="ruleCredentials(rule)">本次密码</button><button class="link" @click="automation.forget(rule.id)">清除本次密码</button><button class="link" @click="deleteSchedule=false;deleteId=rule.id">删除规则</button></div></div></article></div>
   </template></section>
   <section class="card min-w-0"><div class="section-title"><h3>处理队列</h3><select v-model="filter" class="button" data-testid="workflow-queue-filter"><option value="waiting">等待与排队</option><option value="running">正在运行</option><option value="completed">已完成</option><option value="unfinished">未完成</option><option value="all">全部记录</option></select></div><p class="muted mb-3">一次执行一套工作流，手动运行期间自动排队；失败不会反复重试。已排队项使用当时的方案与保存位置。</p>
    <div class="queue-list custom-scrollbar" data-testid="workflow-queue-list"><article v-for="item in visible" :key="item.id" class="queue-item" :data-workflow-queue="item.id"><div class="queue-top"><strong>{{ item.paths[0]?.replaceAll('\\','/').split('/').pop()||item.sourceKey }}</strong><span class="badge" :class="{enabled:item.state==='completed',failure:['failed','stopped','interrupted'].includes(item.state)}">{{ workflowQueueStatuses[item.state] }}</span></div><p class="muted">{{ item.ruleName }} · {{ new Date(item.createdAt).toLocaleString() }}</p><p class="source-path">{{ item.paths[0]||item.sourceKey }}<span v-if="item.paths.length>1"> · 整组 {{ item.paths.length }} 个成员</span></p><p v-if="item.trigger==='schedule'" class="muted">定时 · 约定 {{ new Date(item.scheduledAt||item.createdAt).toLocaleString() }}{{ item.explicit?' · 主动运行':'' }}</p><p class="reason">{{ item.reason }}</p><p v-if="isRulePaused(item)&&!workflowQueueTerminal(item.state)&&item.state!=='running'" class="muted">所属规则已暂停，启用后继续等待。</p><div class="buttons mt-3"><button v-if="item.state==='missed'" class="button" :data-queue-run-missed="item.id" :disabled="automation.saving" @click="automation.action(item.id,'run_missed')">现在补跑</button><button v-if="item.state==='missed'" class="link" :data-queue-skip="item.id" :disabled="automation.saving" @click="automation.action(item.id,'skip')">跳过错过时段</button><button v-if="item.state==='needs_input'" class="button" :data-queue-credentials="item.id" @click="input(item)">{{ automation.missingCredentials(item)?'补充本次密码':'调整本次密码' }}</button><button v-if="item.runId" class="button" :data-queue-open="item.id" @click="emit('open',item.runId)">{{ ['failed','stopped','interrupted'].includes(item.state)?'查看并纠正继续':'查看运行与结果' }}</button><button v-if="item.originalRunId" class="link" @click="emit('open',item.originalRunId)">原触发运行</button><button v-if="item.state==='running'" class="link" @click="workflow.stop()">停止本次运行</button><button v-if="!workflowQueueTerminal(item.state)&&item.state!=='running'" class="link" :disabled="automation.saving" :data-queue-cancel="item.id" @click="automation.action(item.id,'cancel')">取消此项</button><button v-if="workflowQueueTerminal(item.state)&&ruleExists(item.ruleId)" class="link" :disabled="automation.saving" :data-queue-retry="item.id" @click="automation.action(item.id,'retry')">重新加入队列</button></div></article><div v-if="!visible.length" class="empty"><i class="pi pi-inbox"/><p>这里暂时没有{{ filter==='waiting'?'待处理项':'符合筛选的记录' }}</p><small>启用规则后，到点的计划或变化的资料会出现在这里。</small></div></div>
   </section>
  </div>
  <WorkflowScheduleDialog v-if="scheduleEditor" :rule="scheduleEditor.rule" :plans="workflow.plans" :busy="automation.saving" :error="automation.error" @save="saveSchedule" @close="scheduleEditor=undefined"/>
  <WorkflowDirectoryRuleDialog v-if="editor" :rule="editor.rule" :plans="workflow.plans" :busy="automation.saving" :error="automation.error" @save="save" @close="editor=undefined"/>
  <WorkflowRunDialog v-if="credentialsItem" :key="credentialsItem.id" :plan="normalizeWorkflowPlan(credentialsItem.plan)" :initial="{paths:credentialsItem.paths,outputDirectory:credentialsItem.outputDirectory,...automation.sessionFor(credentialsItem.ruleId)}" :input-credential="{visible:['extract','convert'].includes(credentialsItem.plan.steps.find(step=>step.kind!=='filter')?.kind||''),required:false,label:'原始来源密码（可留空）'}" queued recovery @close="credentialsItem=undefined" @run="credentialRequest"><template #before><p class="notice">用于「{{ credentialsItem.ruleName }}」当前会话的后续触发，不会保存到规则或队列。关闭应用后需重新提供；保存密码后仍按队列状态执行。</p></template></WorkflowRunDialog>
  <Modal :visible="!!deleteId" :title="deleteSchedule?'删除这条定时规则？':'删除这条目录规则？'" size="sm" :show-footer="true" @update:visible="deleteId=''"><p class="muted">待执行项会取消，正在运行的工作流、运行记录和已有文件保留。</p><template #footer><button class="button" @click="deleteId=''">返回</button><button class="button" :disabled="automation.saving" @click="deleteSchedule?automation.scheduleAction(deleteId,'delete'):automation.removeRule(deleteId);deleteId=''">删除规则</button></template></Modal>
 </section>
</template>
<style scoped>
.automation{min-width:0}.automation-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}.automation h2{font-size:20px;font-weight:900}.automation h3{font-size:13px;font-weight:900}.muted{font-size:11px;line-height:1.9;color:var(--text-muted);overflow-wrap:anywhere}.buttons{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-width:0;border:1px solid var(--border-subtle);background:var(--bg-input);color:var(--text-content);font-size:11px;padding:9px 12px;border-radius:10px}.button.primary{color:white;background:var(--dynamic-accent)}.button:disabled,.link:disabled{opacity:.45}.link{font-size:11px;color:var(--dynamic-accent)}.notice{font-size:12px;line-height:1.9;border:1px solid var(--border-subtle);border-radius:12px;padding:12px 16px;background:var(--bg-card);margin-bottom:16px;overflow-wrap:anywhere}.failure{color:#ef4444!important}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.stats>div{padding:16px 18px;background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:14px}.stats strong{display:block;font-size:21px;font-weight:900;color:var(--dynamic-accent)}.stats span{display:block;font-size:11px;color:var(--text-muted);margin-top:5px}.automation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}.card{border:1px solid var(--border-subtle);border-radius:18px;background:var(--bg-card);padding:20px}.section-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.rule-list{max-height:680px;overflow:auto}.rule{border:1px solid var(--border-subtle);border-radius:13px;overflow:hidden;margin-bottom:10px}.rule-toggle{display:flex;align-items:center;width:100%;padding:14px;gap:12px;min-width:0}.rule-toggle>i:first-child{color:var(--dynamic-accent)}.rule-toggle strong{display:block;font-size:12px;overflow-wrap:anywhere}.rule-toggle small{display:block;margin-top:5px;font-size:10px;color:var(--text-muted);overflow-wrap:anywhere}.rule-details{padding:0 14px 14px}.rule-details dl{font-size:11px;line-height:1.9}.rule-details dt{margin-top:8px;color:var(--text-muted)}.rule-details dd{overflow-wrap:anywhere}.badge{font-size:10px;border:1px solid var(--border-subtle);border-radius:20px;padding:4px 8px;white-space:nowrap;color:var(--text-muted);flex-shrink:0}.badge.enabled{color:var(--dynamic-accent);background:color-mix(in srgb,var(--dynamic-accent) 6%,transparent)}.queue-list{max-height:680px;overflow:auto;min-width:0}.queue-item{padding:15px;border:1px solid var(--border-subtle);background:var(--bg-input);border-radius:13px;margin-bottom:12px;min-width:0}.queue-top{display:flex;gap:12px;align-items:flex-start;justify-content:space-between}.queue-top strong{font-size:12px;overflow-wrap:anywhere;min-width:0}.source-path{font-size:10px;color:var(--text-muted);overflow-wrap:anywhere;line-height:1.8;margin:9px 0}.reason{font-size:11px;line-height:1.9;overflow-wrap:anywhere}.empty{text-align:center;padding:45px 16px;font-size:12px}.empty i{font-size:26px;color:var(--dynamic-accent)}.empty p{margin-top:15px;font-weight:700}.empty small{display:block;font-size:11px;color:var(--text-muted);line-height:1.9;margin-top:8px}@media(max-width:1050px){.automation-grid{grid-template-columns:minmax(0,1fr)}.rule-list{max-height:350px}.queue-list{max-height:550px}}@media(max-width:800px){.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stats>div{padding:12px 14px}.card{padding:14px}.automation-grid{gap:16px}.rule-toggle{padding:12px;gap:8px}.queue-item{padding:12px}}
</style>
